'use client';
import Link from 'next/link';
import { useCallback, useEffect, useState } from 'react';
import { bnDigits } from '@/core/journey/journey';
import type { Task } from '@/core/journey/tasks';
import { api } from '@/lib/api';
import { bnDate, semLabel } from '@/lib/journey-ui';
import { yearlyHref } from './AdminCalendar';
import { useToast } from './Toast';
import { field, primary, small } from './ui';

type SemesterStart = Extract<Task, { type: 'NEXT_SEMESTER_START' }>;

/** হোম: only what needs doing, generated by the server. Ignoring a card breaks nothing. */
export function AdminHome() {
  const toast = useToast();
  const [state, setState] = useState<{ tasks?: Task[]; error?: string } | null>(null);
  const [version, setVersion] = useState(0);

  useEffect(() => {
    let live = true;
    api<{ tasks: Task[] }>(`/api/admin/tasks?_=${Date.now()}`).then((r) => {
      if (live) setState(r.ok ? { tasks: r.data.tasks } : { error: r.message });
    });
    return () => {
      live = false;
    };
  }, [version]);

  /** Same date for several series: one request per distinct date. */
  const saveStarts = useCallback(
    async (semesterNo: number, items: { seriesId: number; date: string }[]) => {
      const byDate = new Map<string, number[]>();
      for (const i of items) byDate.set(i.date, [...(byDate.get(i.date) ?? []), i.seriesId]);
      for (const [asOfDate, seriesIds] of byDate) {
        const r = await api('/api/admin/positions/bulk', {
          method: 'POST',
          body: { seriesIds, kind: 'SEMESTER_START', asOfDate, semesterNo },
        });
        if (!r.ok) return toast(r.message, 'error');
      }
      toast('শুরুর তারিখ সংরক্ষণ হয়েছে।');
      setVersion((v) => v + 1);
    },
    [toast],
  );

  if (!state) return <p className="px-1 text-sm">লোড হচ্ছে…</p>;
  if (state.error) {
    return (
      <p role="alert" className="px-1 text-sm text-red-700 dark:text-red-400">
        করণীয় আনা যায়নি: {state.error}
      </p>
    );
  }
  if (state.tasks!.length === 0) {
    return (
      <p className="rounded-lg border border-emerald-300 bg-emerald-50 p-4 text-center font-medium text-emerald-950 dark:border-emerald-800 dark:bg-emerald-950 dark:text-emerald-50">
        সব ঠিক আছে ✓
      </p>
    );
  }
  return (
    <ul className="space-y-3">
      {state.tasks!.map((t, i) => (
        <li key={`${t.type}-${i}`}>
          {t.type === 'NEXT_SEMESTER_START' && <StartCard task={t} onSave={saveStarts} />}
          {t.type === 'NEW_BATCH' && <NewBatchCard task={t} onSave={saveStarts} />}
          {t.type === 'YEARLY_DATES' && (
            <Card
              title={`${bnDigits(t.year)} সালের ${bnDigits(t.rules.length)}টি ছুটির তারিখ দিতে হবে`}
            >
              <p className="text-sm text-zinc-700 dark:text-zinc-300">
                {t.rules.map((r) => r.title).join(', ')}
              </p>
              <Link href={yearlyHref(t.year)} className={`${primary} inline-block`}>
                তারিখ দিন
              </Link>
            </Card>
          )}
          {t.type === 'CONFIRM_MOON' && (
            <Card title="চাঁদ দেখা নিশ্চিত করুন (ঐচ্ছিক)">
              <ul className="space-y-0.5 text-sm text-zinc-700 dark:text-zinc-300">
                {t.items.map((x) => (
                  <li key={`${x.ruleId}-${x.year}`}>
                    {x.title} · ~{bnDate(x.startDate)}
                  </li>
                ))}
              </ul>
              <Link href={yearlyHref(t.items[0]!.year)} className={`${small} inline-block`}>
                বছরের ছুটির তালিকা
              </Link>
            </Card>
          )}
        </li>
      ))}
    </ul>
  );
}

function Card({
  title,
  badge,
  children,
}: {
  title: string;
  badge?: string;
  children: React.ReactNode;
}) {
  return (
    <section
      className={`space-y-3 rounded-lg border p-3 ${
        badge
          ? 'border-red-400 bg-red-50 dark:border-red-800 dark:bg-red-950'
          : 'border-zinc-200 dark:border-zinc-800'
      }`}
    >
      <h2 className="flex flex-wrap items-center gap-2 font-semibold">
        {badge && (
          <span className="rounded bg-red-700 px-1.5 py-0.5 text-xs font-medium text-white">
            {badge}
          </span>
        )}
        {title}
      </h2>
      {children}
    </section>
  );
}

function StartCard({
  task: t,
  onSave,
}: {
  task: SemesterStart;
  onSave: (semesterNo: number, items: { seriesId: number; date: string }[]) => Promise<unknown>;
}) {
  const [mode, setMode] = useState<'same' | 'diff'>('same');
  const [date, setDate] = useState(t.projectedStart);
  const [each, setEach] = useState<Record<number, string>>({});
  const [busy, setBusy] = useState(false);
  const dateOf = (id: number, projected: string) => each[id] ?? projected;

  async function submit() {
    setBusy(true);
    await onSave(
      t.semesterNo,
      t.items.map((i) => ({
        seriesId: i.seriesId,
        date: mode === 'same' ? date : dateOf(i.seriesId, i.projectedStart),
      })),
    );
    setBusy(false);
  }

  return (
    <Card
      badge={t.overdue ? 'বাকি' : undefined}
      title={`${bnDigits(t.intakeYear)} সিরিজ · ${bnDigits(t.items.length)}টি ডিপার্টমেন্ট · ${semLabel(t.semesterNo)} এর ক্লাস কবে শুরু?`}
    >
      <div role="group" aria-label="তারিখ দেওয়ার ধরন" className="flex flex-wrap gap-2">
        {(
          [
            ['same', 'সবার জন্য একই'],
            ['diff', 'কয়েকটা আলাদা'],
          ] as const
        ).map(([m, label]) => (
          <button
            key={m}
            type="button"
            aria-pressed={mode === m}
            onClick={() => setMode(m)}
            className={`${small} ${mode === m ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-950' : ''}`}
          >
            {label}
          </button>
        ))}
      </div>
      {mode === 'same' ? (
        <label className="block text-sm font-medium">
          প্রথম ক্লাসের দিন{' '}
          <span className="font-normal text-zinc-500">(আনুমানিক: {bnDate(t.projectedStart)})</span>
          <input
            type="date"
            className={field}
            value={date}
            onChange={(e) => setDate(e.target.value)}
          />
        </label>
      ) : (
        <ul className="grid gap-2 sm:grid-cols-2">
          {t.items.map((i) => (
            <li key={i.seriesId}>
              <label className="block text-sm font-medium">
                {bnDigits(i.label)}
                <input
                  type="date"
                  className={field}
                  value={dateOf(i.seriesId, i.projectedStart)}
                  onChange={(e) => setEach((m) => ({ ...m, [i.seriesId]: e.target.value }))}
                />
              </label>
            </li>
          ))}
        </ul>
      )}
      <button
        type="button"
        className={primary}
        disabled={busy || (mode === 'same' && !date)}
        onClick={submit}
      >
        {busy ? 'সংরক্ষণ হচ্ছে…' : 'সংরক্ষণ'}
      </button>
    </Card>
  );
}

function NewBatchCard({
  task: t,
  onSave,
}: {
  task: Extract<Task, { type: 'NEW_BATCH' }>;
  onSave: (semesterNo: number, items: { seriesId: number; date: string }[]) => Promise<unknown>;
}) {
  const [date, setDate] = useState('');
  const [busy, setBusy] = useState(false);
  return (
    <Card
      title={`${bnDigits(t.intakeYear)} সিরিজ · ${bnDigits(t.seriesIds.length)}টি ডিপার্টমেন্ট · শুরুর তারিখ দিন`}
    >
      <p className="text-sm text-zinc-700 dark:text-zinc-300">
        নতুন ব্যাচ হলে ১-১ এর প্রথম ক্লাসের দিন দিন। আগে থেকে চলছে এমন সিরিজ হলে সিরিজ বোর্ডে এখনকার
        অবস্থা দিন।
      </p>
      <label className="block text-sm font-medium">
        ১-১ এর প্রথম ক্লাসের দিন
        <input
          type="date"
          className={field}
          value={date}
          onChange={(e) => setDate(e.target.value)}
        />
      </label>
      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          className={primary}
          disabled={busy || !date}
          onClick={async () => {
            setBusy(true);
            await onSave(
              1,
              t.seriesIds.map((seriesId) => ({ seriesId, date })),
            );
            setBusy(false);
          }}
        >
          {busy ? 'সংরক্ষণ হচ্ছে…' : 'সংরক্ষণ'}
        </button>
        <Link href="/admin?tab=board" className={`${small} px-3 py-2`}>
          সিরিজ বোর্ডে অবস্থা দিন
        </Link>
      </div>
    </Card>
  );
}
